with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published)
select id,'رادار الطقس والتنبؤ الآني المتقدم','فيزياء الرادار والاستقطاب ودوبلر وتقدير الهطول وتتبع الخلايا ودمج المصادر والتحقق التشغيلي.',50,false from c
on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'فيزياء الرادار ومنتجاته',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التنبؤ الآني والتحقق التشغيلي',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('weather-radar-equation','معادلة الرادار الجوي','القدرة المنقولة والهدف والانعكاسية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تعتمد معادلة الرادار على خصائص المرسل والهوائي والمسافة وطول الموجة والهدف والانتشار الجوي. تتغير صياغة المعادلة بحسب نوع الرادار والهدف، ويجب التمييز بين القدرة المستقبلة والانعكاسية المحسوبة بعد المعالجة."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق معادلة الرادار الجوي توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق معادلة الرادار الجوي، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد العوامل التي تجعل إشارة هدفين متساويي الحجم مختلفة عند الرادار، وناقش أثر المسافة."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز معادلة الرادار الجوي القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6160,55,'["شرح المبادئ العلمية في معادلة الرادار الجوي","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
('radar-reflectivity-factor','عامل الانعكاسية الرادارية Z','توزيع أحجام القطرات وعلاقة الانعكاسية بالهطول','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يعبر عامل الانعكاسية عن مجموع مساهمات أقطار الهيدروميتورات تقريباً وفق القوة السادسة للقطر في تعريفه التقليدي. لذلك تؤثر القطرات الكبيرة بقوة في القيمة، ولا يتحول Z إلى معدل هطول إلا بعلاقة تجريبية ملائمة لنوع الهطول."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق عامل الانعكاسية الرادارية Z توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق عامل الانعكاسية الرادارية Z، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا يمكن لقطرات كبيرة قليلة أن تؤثر بقوة في الانعكاسية مقارنة بقطرات صغيرة كثيرة."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز عامل الانعكاسية الرادارية Z القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6170,55,'["شرح المبادئ العلمية في عامل الانعكاسية الرادارية Z","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
('radar-dbz-interpretation','قراءة مقياس dBZ وتفسيره','المقياس اللوغاريتمي للانعكاسية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يعرض dBZ الانعكاسية بمقياس لوغاريتمي، ما يسمح بإظهار نطاق واسع من الشدات. لا تمثل القيمة وحدها معدل المطر أو شدة الخطر، لأن نوع الهيدروميتور والتوهين والثلج والبرد تؤثر في العلاقة."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق قراءة مقياس dBZ وتفسيره توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق قراءة مقياس dBZ وتفسيره، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن معنى زيادة 10 dB في الانعكاسية مع زيادة خطية، ووضح لماذا يلزم الحذر في تقدير المطر."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز قراءة مقياس dBZ وتفسيره القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6180,55,'["شرح المبادئ العلمية في قراءة مقياس dBZ وتفسيره","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
('radar-attenuation-correction','توهين إشارة الرادار وتصحيحه','امتصاص الإشارة وانتثارها خلف الهطول الشديد','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يضعف الهطول الشديد الإشارة الرادارية أثناء انتقالها ذهاباً وإياباً، وقد يؤدي ذلك إلى تقليل تقدير الانعكاسية خلف الخلية. تعتمد المعالجة على خصائص الحزمة والهيدروميتورات وتقدير مسار التوهين."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق توهين إشارة الرادار وتصحيحه توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق توهين إشارة الرادار وتصحيحه، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد نمطاً مكانياً قد يشير إلى توهين خلف خلية قوية، واذكر اختباراً لتأكيده."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز توهين إشارة الرادار وتصحيحه القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6190,55,'["شرح المبادئ العلمية في توهين إشارة الرادار وتصحيحه","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
('radar-beam-blockage','حجب حزمة الرادار بالتضاريس','الأقنعة التضاريسية وفقدان التغطية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تحجب الجبال أو المنشآت جزءاً من الحزمة أو كلها، ما يسبب نقصاً في الرصد لا يعني غياب الهطول. تستخدم خرائط الحجب وارتفاع الحزمة وزوايا المسح لتقييم المناطق غير الممثلة."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق حجب حزمة الرادار بالتضاريس توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق حجب حزمة الرادار بالتضاريس، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف تميز منطقة ظل راداري عن منطقة خالية فعلاً من الهطول بالاستعانة بمصادر أخرى."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز حجب حزمة الرادار بالتضاريس القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6200,55,'["شرح المبادئ العلمية في حجب حزمة الرادار بالتضاريس","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
('radar-bright-band','النطاق اللامع في الرادار','طبقة الانصهار وأثرها في الانعكاسية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تظهر زيادة انعكاسية قرب مستوى انصهار الثلج بسبب تحول البلورات المغطاة بالماء إلى قطرات أو جسيمات رطبة ذات استجابة رادارية قوية. ينبغي عدم تفسير هذه الزيادة تلقائياً على أنها مطر سطحي شديد."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق النطاق اللامع في الرادار توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق النطاق اللامع في الرادار، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اربط ارتفاع النطاق اللامع بمستوى الصفر الحراري والسبر الرأسي."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز النطاق اللامع في الرادار القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6210,55,'["شرح المبادئ العلمية في النطاق اللامع في الرادار","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
('radar-dual-polarization','الرادار ثنائي الاستقطاب','الانعكاسية التفاضلية والطور النوعي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس الرادار ثنائي الاستقطاب خصائص الإشارة في اتجاهين استقطابيين، ويوفر مؤشرات مثل ZDR وKDP وρhv لتحسين تصنيف الهيدروميتورات وتقدير الهطول. تتطلب القراءة فهماً لجودة الإشارة والبيئة الرادارية."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق الرادار ثنائي الاستقطاب توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق الرادار ثنائي الاستقطاب، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف تساعد مجموعة مؤشرات استقطابية في التمييز بين مطر وثلج رطب دون الاعتماد على مؤشر منفرد."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز الرادار ثنائي الاستقطاب القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6220,55,'["شرح المبادئ العلمية في الرادار ثنائي الاستقطاب","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
('radar-hydrometeor-classification','تصنيف الهيدروميتورات رادارياً','تمييز المطر والثلج والبرد والأنواع المختلطة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم خوارزميات التصنيف خصائص الاستقطاب والحرارة والارتفاع والانعكاسية لتقدير نوع الجسيمات. يبقى التصنيف احتماليّاً ويتأثر بحدود الخوارزمية وتداخل الأنواع وجودة القياس."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق تصنيف الهيدروميتورات رادارياً توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق تصنيف الهيدروميتورات رادارياً، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم شجرة قرار مبسطة لتصنيف المطر والثلج والبرد مع وضع حالة غير مؤكدة."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز تصنيف الهيدروميتورات رادارياً القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6230,55,'["شرح المبادئ العلمية في تصنيف الهيدروميتورات رادارياً","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
('radar-wind-retrieval-doppler','استخراج الرياح من دوبلر الراداري','السرعة الشعاعية وحدود اتجاه القياس','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس دوبلر المركبة الشعاعية للسرعة على خط النظر، ولا يقيس متجه الرياح الكامل من مسح منفرد. يتطلب استنتاج الرياح الأفقية أو الرأسية افتراضات أو مسوحاً متعددة أو دمجاً مع بيانات أخرى."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق استخراج الرياح من دوبلر الراداري توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق استخراج الرياح من دوبلر الراداري، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا لا تكفي السرعة الشعاعية وحدها لمعرفة اتجاه الرياح الكامل."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز استخراج الرياح من دوبلر الراداري القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6240,55,'["شرح المبادئ العلمية في استخراج الرياح من دوبلر الراداري","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
('radar-mosaicking-composites','دمج صور الرادارات وإنتاج المركبات','المعايرة والتداخل والمطابقة المكانية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تجمع منتجات عدة رادارات لتوفير تغطية أوسع، مع ضرورة توحيد المعايرة والإسقاط والدقة الزمنية ومعالجة مناطق التداخل. قد تنشأ حدود مصطنعة إذا اختلفت خصائص الأجهزة أو طرق الدمج."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق دمج صور الرادارات وإنتاج المركبات توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق دمج صور الرادارات وإنتاج المركبات، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد اختبارات جودة لمركب إقليمي قبل استخدامه في متابعة العواصف."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز دمج صور الرادارات وإنتاج المركبات القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6250,55,'["شرح المبادئ العلمية في دمج صور الرادارات وإنتاج المركبات","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'فيزياء الرادار ومنتجاته'),
