('radar-quantitative-precipitation-estimation','تقدير كميات الهطول الراداري QPE','التجميع الزمني والدمج متعدد المصادر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تنتج QPE تقديراً مكانياً للهطول خلال فترة محددة، وتدمج أحياناً الرادار ومقاييس المطر والأقمار والنماذج. يجب تعريف الفترة والتراكم والوحدة وطرق معالجة القيم المفقودة."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق تقدير كميات الهطول الراداري QPE توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق تقدير كميات الهطول الراداري QPE، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم سير عمل لإنتاج تراكم مطري ساعي ويومي مع مقارنة محطات أرضية."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز تقدير كميات الهطول الراداري QPE القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6290,55,'["شرح المبادئ العلمية في تقدير كميات الهطول الراداري QPE","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'التنبؤ الآني والتحقق التشغيلي'),
('radar-quantitative-precipitation-forecast','التنبؤ الكمي بالهطول QPF','التوقع المكاني والزماني لكمية المطر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يركز QPF على كمية الهطول المتوقعة خلال نافذة زمنية ومكانية. يعتمد على الحالة الابتدائية والديناميكيات والفيزياء والبيانات، ويجب عرضه بنطاقات أو احتمالات عندما تكون الثقة محدودة."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق التنبؤ الكمي بالهطول QPF توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق التنبؤ الكمي بالهطول QPF، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ميز بين توقع كمية المطر واحتمال تجاوز عتبة مطرية، وقدم مثالاً على اختلاف دلالتهما."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز التنبؤ الكمي بالهطول QPF القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6300,55,'["شرح المبادئ العلمية في التنبؤ الكمي بالهطول QPF","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'التنبؤ الآني والتحقق التشغيلي'),
('satellite-radar-sensor-fusion','دمج بيانات الأقمار والرادار','تكامل التغطية والخصائص الفيزيائية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يوفر الرادار معلومات تفصيلية عن الهطول ضمن مدى تغطيته، بينما تعطي الأقمار تغطية أوسع وخصائص سحابية وحرارية. يحسن الدمج التقدير عند مراعاة اختلاف المتغيرات والدقة والتواتر وأخطاء كل مصدر."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق دمج بيانات الأقمار والرادار توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق دمج بيانات الأقمار والرادار، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح طريقة دمج لرصد منطقة لا يغطيها الرادار مع توضيح دور القمر الصناعي."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز دمج بيانات الأقمار والرادار القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6310,55,'["شرح المبادئ العلمية في دمج بيانات الأقمار والرادار","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'التنبؤ الآني والتحقق التشغيلي'),
('nowcasting-lightning-integration','دمج بيانات البرق في التنبؤ الآني','معدل الوميض وتطور الحمل الحراري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد يشير تغير نشاط البرق إلى تطور الحمل الحراري، لكنه لا يحدد وحده شدة الهطول أو الخطر. يفيد دمجه مع الرادار والأقمار والسبر في بناء صورة آنية متعددة المصادر."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق دمج بيانات البرق في التنبؤ الآني توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق دمج بيانات البرق في التنبؤ الآني، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد كيف يمكن استخدام اتجاه تغير نشاط البرق كإشارة مساندة لا كإنذار مستقل."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز دمج بيانات البرق في التنبؤ الآني القدرة على قراءة بيانات الرصد ال