('nowcasting-probabilistic-products','المنتجات الاحتمالية للتنبؤ الآني','احتمال الحدث ومجالات الثقة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تعبر المنتجات الاحتمالية عن عدم اليقين في حدوث الظاهرة أو تجاوز عتبة، وتحتاج إلى معايرة وفحص الاعتمادية والتمييز. لا تعني احتمالية 60% أن الحدث سيغطي 60% من الموقع أو الزمن بالضرورة."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق المنتجات الاحتمالية للتنبؤ الآني توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق المنتجات الاحتمالية للتنبؤ الآني، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر احتمال هطول 60% ضمن تعريف مكاني وزمني واضح، واذكر كيف تقيم اعتماديته."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز المنتجات الاحتمالية للتنبؤ الآني القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6330,55,'["شرح المبادئ العلمية في المنتجات الاحتمالية للتنبؤ الآني","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'التنبؤ الآني والتحقق التشغيلي'),
('radar-nowcasting-verification','التحقق من التنبؤ الآني الراداري','POD وFAR وCSI ومطابقة الإزاحة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم مقاييس مثل POD وFAR وCSI لتقييم كشف الأحداث، مع أهمية العتبة والنافذة الزمنية والمكانية. ينبغي تحليل الإنذارات الفائتة والكاذبة والانحياز إلى جانب مقاييس الإزاحة."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق التحقق من التنبؤ الآني الراداري توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق التحقق من التنبؤ الآني الراداري، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"احسب POD وFAR من جدول أحداث افتراضي، ثم اشرح كيف يؤثر اختيار عتبة dBZ في النتيجة."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز التحقق من التنبؤ الآني الراداري القدرة على قراءة بيانات الرصد المتقدم وتحويلها إلى معلومات قابلة للتحقق، مع المحافظة على الفصل بين القياس والتقدير والتنبؤ."}]}'::jsonb,6340,55,'["شرح المبادئ العلمية في التحقق من التنبؤ الآني الراداري","فحص جودة البيانات وتفسير المنتج","تقييم حدود الاستنتاج والتنبؤ"]'::jsonb,'التنبؤ الآني والتحقق التشغيلي'),
('operational-nowcasting-workflow','سير العمل التشغيلي للتنبؤ الآني','المراقبة المستمرة والتحديث وإصدار المنتجات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتطلب التنبؤ الآني تدفقاً مستمراً للبيانات وضبط جودة تلقائياً ومراقبة تطور الحالات وإصدار تحديثات متكررة. يجب توثيق وقت المنتج ومصدره وحدود الثقة، واتباع إجراءات المركز المعتمدة عند التصعيد."},{"type":"heading","text":"المدخلات ومراقبة الجودة"},{"type":"text","text":"يتطلب تطبيق سير العمل التشغيلي للتنبؤ الآني توثيق نوع المستشعر وزاوية المسح والارتفاع والدقة المكانية والزمنية والمعايرة وإصدار الخوارزمية. يجب التمييز بين الإشارة المقاسة والمنتج المستنتج، وإظهار المناطق التي لا تتوافر فيها تغطية موثوقة."},{"type":"heading","text":"خطوات التحليل"},{"type":"list","items":["التحقق من سلامة البيانات والطابع الزمني والوحدات.","فحص أثر التضاريس والمدى والتوهين وجودة الإشارة.","مقارنة المنتج بمصدر رصد مستقل عند توفره.","تتبع التغير عبر المسوح المتتابعة بدلاً من قراءة لقطة واحدة.","توثيق العتبات والافتراضات وحدود الاستخدام التشغيلي."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة رصدية","text":"في تطبيق سير العمل التشغيلي للتنبؤ الآني، اختر فترة ذات بيانات متتابعة، ثم استخرج المنتج المطلوب وقارنه ببيانات داعمة. افصل بين ما يظهر مباشرة في القياس وما تستنتجه الخوارزمية، وسجل مناطق الشك أو فقدان التغطية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم قائمة تحقق لمناوبة تنبؤ آني تبدأ بفحص تدفق البيانات وتنتهي بتوثيق التحديث."},{"type":"heading","text":"أخطاء يجب تجنبها"},{"type":"list","items":["اعتبار اللون أو العتبة دليلاً مباشراً على نوع الهطول أو الخطر.","إهمال مناطق الظل أو التوهين أو فقدان البيانات.","مقارنة منتجات تختلف في زمن المسح أو الدقة دون مواءمة.","إصدار استنتاج قطعي من مؤشر واحد أو لقطة منفردة."]},{"type":"callout","text":"تنبيه تشغيلي: منتجات الرادار والتنبؤ الآني أدوات دعم قرار، ويجب دمجها مع الرصد والتحليل وإجراءات التحذير الرسمية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يعزز سير العمل التشغيلي ل